  };
}
function extractWikiTargets(body = '') {
  const targets = [];
  const re = /\[\[([^\]\n|#]+)(?:#[^\]\n|]+)?(?:\|[^\]\n]+)?\]\]/g;
  let match;
  while ((match = re.exec(String(body || '')))) {
