const fs = require('node:fs');
const path = require('node:path');
const { withIsolatedStore } = require('./tests/helpers/common');
(async () => {
  await withIsolatedStore(async (store) => {
    const real = path.join(store.ROOT, 'personal');
    fs.writeFileSync(store.__test.CONFIG_FILE, JSON.stringify({
      vaults: [{ id: '../bad', name: 'Bad', slug: 'personal', path: '/tmp/forged' }],
      activeVaultId: '../bad', tweaks: null, aiConfig: null,
    }), 'utf8');
    store.__test.clearConfigCache();
    const vaults = await store.listVaults();
    console.log(vaults);
    console.log(await store.loadConfig());
  });
})().catch(e => { console.error(e); process.exit(1); });
NODE"

